<?php
declare(strict_types=1);
$root=dirname(__DIR__,2);$adminTemplate=(string)file_get_contents($root.'/templates/admin.php');$appTemplate=(string)file_get_contents($root.'/templates/index.php');$accessScript=is_file($root.'/js/admin-access.js')?(string)file_get_contents($root.'/js/admin-access.js'):'';$pageController=(string)file_get_contents($root.'/lib/Controller/PageController.php');$middleware=(string)file_get_contents($root.'/lib/Middleware/BrAccessMiddleware.php');$routes=(string)file_get_contents($root.'/appinfo/routes.php');
foreach(['brtop-full-access-form','brtop-full-access-enabled','brtop-full-access-history','Maximal 24 Stunden']as$contract){if(!str_contains($appTemplate,$contract))throw new RuntimeException("Rollenabhängige Fachapp-Steuerung fehlt: {$contract}");if(str_contains($adminTemplate,$contract))throw new RuntimeException("Steuerung liegt noch im technischen Adminbereich: {$contract}");}
