foreach(['brtop-admin-access-warning','<details','<summary','Datenschutzbeauftragte','target="_blank"','rel="noopener noreferrer"']as$contract)if(!str_contains($appTemplate,$contract))throw new RuntimeException("Kompakte Vollzugriffswarnung am App-Titel fehlt: {$contract}");
